{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Living systematic review and meta-analysis.",
      "reason": "The phrase explicitly identifies the report as a systematic review (and meta-analysis)."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Cohort studies reporting the rates, clinical manifestations (symptoms, laboratory and radiological findings), risk factors, and maternal and perinatal outcomes in pregnant and recently pregnant women with suspected or confirmed covid-19.",
      "reason": "This describes the population and main objectives (clinical manifestations, risk factors, maternal and perinatal outcomes in pregnant and recently pregnant women with covid-19), indicating the title provides key information about population and exposure."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "This article is a living systematic review that will be updated to reflect emerging evidence.",
      "reason": "The review explicitly states its living-review/update status, which is relevant supplementary information for the title."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "In this unprecedented pandemic situation, where evidence is rapidly produced and published in various formats, our living systematic review underpinned by robust methods and continually updated at regular intervals is important for several reasons. Firstly, it addresses important research questions relevant to clinical decision making and policies. Secondly, uncertainties remain for key outcomes that require further evidence.",
      "reason": "Explicitly describes the current state (rapidly produced evidence, evolving pandemic) and notes remaining uncertainties for key outcomes."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Pregnant women are considered a high risk group because of concerns about the effect of covid-19 on them during and after pregnancy, and on their neonates. Quantification of the rates of covid-19, its risk factors, clinical manifestations, and outcomes is key to planning clinical maternal care and management in an evolving pandemic scenario.",
      "reason": "Explains the importance and need for the review by identifying pregnant women as a high-risk group and stating that quantification of rates, risk factors and outcomes is key for clinical care and management."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "This article is a living systematic review that will be updated to reflect emerging evidence. Updates may occur for up to two years from the date of original publication. This version is update 2 of the original article published on 1 September 2020 ( BMJ 2020;370:m3320), and previous updates can be found as data supplements (https:/ /www.bmj.com/ content/370/bmj.m3320/related#datasupp).",
      "reason": "Identifies previous versions/updates of the review and the original publication, explaining this work as an update/continuation and providing citation/link to prior review, thereby justifying need in context of existing similar work."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "Cohort studies reporting the rates, clinical manifestations (symptoms, laboratory and radiological findings), risk factors, and maternal and perinatal outcomes in pregnant and recently pregnant women with suspected or confirmed covid-19.",
      "reason": "The review is of observational cohort studies of disease manifestations/outcomes, not a review of intervention effects; therefore a mechanism of action of an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "Cohort studies reporting the rates, clinical manifestations (symptoms, laboratory and radiological findings), risk factors, and maternal and perinatal outcomes in pregnant and recently pregnant women with suspected or confirmed covid-19.",
      "reason": "The review does not assess complex interventions or delivery contexts that would require a logic model; it synthesises observational data on disease rates, manifestations, and outcomes."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "Our systematic review is based on a prospectively registered protocol (PROSPERO CRD42020178076; registered 22 April 2020) 19 to evaluate a series of research questions on covid-19 during and after pregnancy. We report our findings on the rates, clinical manifestations, risk factors, and maternal and perinatal outcomes in women with covid-19 in line with the preferred reporting items for systematic reviews and meta-analyses (PRISMA) recommendations (see appendix 1).",
      "reason": "The objectives (to evaluate research questions on COVID-19 in pregnancy and to report findings on rates, clinical manifestations, risk factors, and maternal and perinatal outcomes) are explicitly stated, but they are not presented in a formal question‑formulation framework (eg, PICO) as required by this element."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "Cohort studies reporting the rates, clinical manifestations (symptoms, laboratory and radiological findings), risk factors, and maternal and perinatal outcomes in pregnant and recently pregnant women with suspected or confirmed covid-19.",
      "reason": "The review concerns observational cohort studies of rates, manifestations, risk factors, and outcomes rather than interventions; therefore planned intervention comparisons using PICO are not applicable."
    }
  ],
  "confidence": 75
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "We included studies that compared covid-19 rates, clinical manifestations (symptoms, laboratory and radiological results), risk factors, and associated mortality and morbidity between pregnant and recently pregnant and non-pregnant women of reproductive age, and those that compared maternal and perinatal outcomes in pregnant women with and without covid-19. In studies comparing maternal and perinatal outcomes of pregnant women with covid-19 to those without, we classified the comparative controls as being historical if the cohort of pregnant women without covid-19 gave birth before December 2019. Studies on noncomparative cohorts with a minimum of 10 participants were included if they reported on the rates and clinical manifestations of covid-19 and relevant outcomes in pregnant and recently pregnant women. We defined cohort studies as those that sampled participants on the basis of exposure, followed-up participants over time, and ascertained the outcomes.",
      "reason": "Specifies study designs (cohort), minimum sample size for noncomparative cohorts (10), definitions of cohorts, types of comparisons and outcomes eligible, and criteria for historical controls—covering key study characteristics used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "For this second update of the review, we included studies from searches up to 27 April 2021. We contacted established groups ... No language restrictions were applied. Appendix 2 provides details of the search strategies and databases searched. Additional searches were conducted of preprint servers, blogs, websites that serve as repositories for covid-19 studies such as the LOVE platform (Living Overview of the Evidence), 21 social media, guidelines, and reference lists of included studies.",
      "reason": "Reports the search cutoff date (dissemination year window), states no language restrictions, and indicates inclusion of preprints and other nontraditional publications (publication/report status)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No text explicitly distinguishes excluding studies because outcomes were not measured from excluding studies because outcome results were not reported; retrieved evidence does not address this distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "We pooled the comparative dichotomous data using random effects meta-analysis and summarised the findings as odds ratios and risk differences with 95% confidence intervals. ... We undertook subgroup analysis by country status (high income v low and middle income), sampling frame (universal, risk based, and symptom based testing, including not reported), and risk status of women in the studies (high, low, any). Sensitivity analysis was performed by restricting the analysis to women with confirmed covid-19, study quality (high, low), and population (unselected, selected).",
      "reason": "Specifies the groups and subgroup/sensitivity analyses used in syntheses (comparative vs noncomparative data, country status, sampling frame, risk status, confirmed cases, study quality, population), linking them to planned comparisons and syntheses."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "To minimise risk of bias we restricted our meta-analysis to cohort studies, and we reported the quality of the included studies.",
      "reason": "Provides a rationale for the notable restriction of including only cohort studies (to minimise risk of bias)."
    }
  ],
  "confidence": 85
}

