      "reason": "The manuscript specifies that reference lists of included studies were examined."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information is provided about backward or forward citation searching such as seed reports used, the citation index/platform, or the date of such searches."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not report consulting specific journals or conference proceedings; there is no evidence that journals/conference proceedings were separately searched, so this reporting item does not apply based on the supplied evidence."
