{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PARTIAL",
      "chunk_id": "text_15",
      "quote": "We defined women as having confirmed covid-19 if they had laboratory confirmation of SARS-CoV-2 infection irrespective of clinical signs and symptoms. 22 Women with a diagnosis based only on clinical or radiological findings were defined as having suspected covid-19. The recently pregnant group comprised women in the postpartum and post-abortion period. We included studies that compared covid-19 rates, clinical manifestations (symptoms, laboratory and radiological results), risk factors, and associated mortality and morbidity between pregnant and recently pregnant and non-pregnant women of reproductive age, and those that compared maternal and perinatal outcomes in pregnant women with and without covid-19. ... The PROSPERO protocol provides a full list of the risk factors, clinical features, and outcomes evaluated. 19",
      "reason": "The manuscript defines several key variables (confirmed vs suspected COVID-19, recently pregnant) and lists categories sought (covid-19 rates, clinical manifestations, risk factors, mortality/morbidity), and refers to the PROSPERO protocol for the full list. However it does not in the provided text present a complete, detailed list and definitions of all other variables sought within the paper itself, so reporting is partial."
    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "If there was an overlap of data or suspicion of duplicates of participants in studies, we included studies based on their study design (prioritising comparative cohorts), and sample size (larger study prioritised).",
      "reason": "The paper describes an explicit assumption/decision rule for handling overlapping or duplicate participant data (prioritising comparative cohorts and larger sample size). However, other assumptions about missing or unclear study information are not described in the provided evidence, so this is partial."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "Two independent reviewers extracted data using a pre-piloted form.",
      "reason": "The manuscript cites use of a pre-piloted data extraction form (a tool) to determine/collect data items, satisfying the requirement to report any tool used."
    }
  ],
  "confidence": 75
}

